static void __fastcall init_block(deflate_state * s) {
    int n; /* iterates over tree elements */
    /* Initialize the trees. */
    for (n = 0; n < (256 + 1 + 29); n++)
        s->dyn_ltree[n].fc = 0;
    for (n = 0; n < 30; n++)
        s->dyn_dtree[n].fc = 0;
    for (n = 0; n < 19; n++)
        s->bl_tree[n].fc = 0;
    s->dyn_ltree[256].fc = 1;
    s->opt_len = s->static_len = 0L;
    s->last_lit = s->matches = 0;
}

static void __stdcall pqdownheap(int32_t k, deflate_state * s, ct_data * tree) {
    int v = s->heap[k];
    int j = k << 1; /* left son of k */
    while (j <= s->heap_len) {
        /* Set j to the smallest of the two sons: */
        if (j < s->heap_len &&
            (tree[s->heap[j + 1]].fc < tree[s->heap[j]].fc ||
             (tree[s->heap[j + 1]].fc == tree[s->heap[j]].fc &&
              s->depth[s->heap[j + 1]] <= s->depth[s->heap[j]]))) {
            j++;
        }
        /* Exit if v is smaller than both sons */
        if ((tree[v].fc < tree[s->heap[j]].fc ||
             (tree[v].fc == tree[s->heap[j]].fc &&
              s->depth[v] <= s->depth[s->heap[j]])))
            break;
        /* Exchange v with the smallest son */
        s->heap[k] = s->heap[j];
        k = j;
        /* And continue down the tree, setting j to the left son of k */
        j <<= 1;
    }
    s->heap[k] = v;
}

static void gen_bitlen(tree_desc * desc, deflate_state * s) {
    ct_data *tree = desc->dyn_tree;
    int max_code = desc->max_code;
    const ct_data *stree = desc->stat_desc->static_tree;
    const int *extra = desc->stat_desc->extra_bits;
    int base = desc->stat_desc->extra_base;
    int max_length = desc->stat_desc->max_length;
    int h;            /* heap index */
    int n, m;         /* iterate over the tree elements */
    int bits;         /* bit length */
    int xbits;        /* extra bits */
    unsigned short f; /* frequency */
    int overflow = 0; /* number of elements with bit length too large */
    for (bits = 0; bits <= 15; bits++)
        s->bl_count[bits] = 0;
    /* In a first pass, compute the optimal bit lengths (which may
     * overflow in the case of the bit length tree).
     */
    tree[s->heap[s->heap_max]].dl = 0; /* root of the heap */
    for (h = s->heap_max + 1; h < (2 * (256 + 1 + 29) + 1); h++) {
        n = s->heap[h];
        bits = tree[tree[n].dl].dl + 1;
        if (bits > max_length)
            bits = max_length, overflow++;
        tree[n].dl = (unsigned short)bits;
        /* We overwrite tree[n].Dad which is no longer needed */
        if (n > max_code)
            continue; /* not a leaf node */
        s->bl_count[bits]++;
        xbits = 0;
        if (n >= base)
            xbits = extra[n - base];
        f = tree[n].fc;
        s->opt_len += (uint32_t)f * (bits + xbits);
        if (stree)
            s->static_len += (uint32_t)f * (stree[n].dl + xbits);
    }
    if (overflow == 0)
        return;
    /* This happens for example on obj2 and pic of the Calgary corpus */
    /* Find the first bit length which could increase: */
    do {
        bits = max_length - 1;
        while (s->bl_count[bits] == 0)
            bits--;
        s->bl_count[bits]--;        /* move one leaf down the tree */
        s->bl_count[bits + 1] += 2; /* move one overflow item as its brother */
        s->bl_count[max_length]--;
        /* The brother of the overflow item also moves one step up,
         * but this does not affect bl_count[max_length]
         */
        overflow -= 2;
    } while (overflow > 0);
    /* Now recompute all bit lengths, scanning in increasing frequency.
     * h is still equal to HEAP_SIZE. (It is simpler to reconstruct all
     * lengths instead of fixing only the wrong ones. This idea is taken
     * from 'ar' written by Haruhiko Okumura.)
     */
    for (bits = max_length; bits != 0; bits--) {
        n = s->bl_count[bits];
        while (n != 0) {
            m = s->heap[--h];
            if (m > max_code)
                continue;
            if ((unsigned)tree[m].dl != (unsigned)bits) {
                s->opt_len += ((long)bits - (long)tree[m].dl) * (long)tree[m].fc;
                tree[m].dl = (unsigned short)bits;
            }
            n--;
        }
    }
}

static void __stdcall scan_tree(int32_t max_code, deflate_state * s, ct_data * tree) {
    int n;                     /* iterates over all tree elements */
    int prevlen = -1;          /* last emitted length */
    int curlen;                /* length of current code */
    int nextlen = tree[0].dl; /* length of next code */
    int count = 0;             /* repeat count of the current code */
    int max_count = 7;         /* max repeat count */
    int min_count = 4;         /* min repeat count */
    if (nextlen == 0)
        max_count = 138, min_count = 3;
    tree[max_code + 1].dl = (unsigned short)0xffff; /* guard */
    for (n = 0; n <= max_code; n++) {
        curlen = nextlen;
        nextlen = tree[n + 1].dl;
        if (++count < max_count && curlen == nextlen) {
            continue;
        } else if (count < min_count) {
            s->bl_tree[curlen].fc += count;
        } else if (curlen != 0) {
            if (curlen != prevlen)
                s->bl_tree[curlen].fc++;
            s->bl_tree[16].fc++;
        } else if (count <= 10) {
            s->bl_tree[17].fc++;
        } else {
            s->bl_tree[18].fc++;
        }
        count = 0;
        prevlen = curlen;
        if (nextlen == 0) {
            max_count = 138, min_count = 3;
        } else if (curlen == nextlen) {
            max_count = 6, min_count = 3;
        } else {
            max_count = 7, min_count = 4;
        }
    }
}

