static void __stdcall send_all_trees(int32_t lcodes, int32_t dcodes, int32_t blcodes, deflate_state * s) {
    int rank; /* index in bl_order */
    {
        int len = 5;
        if (s->bi_valid > (int)16 - len) {
            int val = lcodes - 257;
            s->bi_buf |= (unsigned short)val << s->bi_valid;
            {
                {
                    s->pending_buf[s->pending++] =
                        ((unsigned char)((s->bi_buf) & 0xff));
                };
                {
                    s->pending_buf[s->pending++] =
                        ((unsigned char)((unsigned short)(s->bi_buf) >> 8));
                };
            };
            s->bi_buf = (unsigned short)val >> (16 - s->bi_valid);
            s->bi_valid += len - 16;
        } else {
            s->bi_buf |= (unsigned short)(lcodes - 257) << s->bi_valid;
            s->bi_valid += len;
        }
    }; /* not +255 as stated in appnote.txt */
    {
        int len = 5;
        if (s->bi_valid > (int)16 - len) {
            int val = dcodes - 1;
            s->bi_buf |= (unsigned short)val << s->bi_valid;
            {
                {
                    s->pending_buf[s->pending++] =
                        ((unsigned char)((s->bi_buf) & 0xff));
                };
                {
                    s->pending_buf[s->pending++] =
                        ((unsigned char)((unsigned short)(s->bi_buf) >> 8));
                };
            };
            s->bi_buf = (unsigned short)val >> (16 - s->bi_valid);
            s->bi_valid += len - 16;
        } else {
            s->bi_buf |= (unsigned short)(dcodes - 1) << s->bi_valid;
            s->bi_valid += len;
        }
    };
    {
        int len = 4;
        if (s->bi_valid > (int)16 - len) {
            int val = blcodes - 4;
            s->bi_buf |= (unsigned short)val << s->bi_valid;
            {
                {
                    s->pending_buf[s->pending++] =
                        ((unsigned char)((s->bi_buf) & 0xff));
                };
                {
                    s->pending_buf[s->pending++] =
                        ((unsigned char)((unsigned short)(s->bi_buf) >> 8));
                };
            };
            s->bi_buf = (unsigned short)val >> (16 - s->bi_valid);
            s->bi_valid += len - 16;
        } else {
            s->bi_buf |= (unsigned short)(blcodes - 4) << s->bi_valid;
            s->bi_valid += len;
        }
    }; /* not -3 as stated in appnote.txt */
    for (rank = 0; rank < blcodes; rank++) {
        {
            int len = 3;
            if (s->bi_valid > (int)16 - len) {
                int val = s->bl_tree[gZlibExtraLBitsBlOrder.bl_order[rank]].dl;
                s->bi_buf |= (unsigned short)val << s->bi_valid;
                {
                    {
                        s->pending_buf[s->pending++] =
                            ((unsigned char)((s->bi_buf) & 0xff));
                    };
                    {
                        s->pending_buf[s->pending++] =
                            ((unsigned char)((unsigned short)(s->bi_buf) >> 8));
                    };
                };
                s->bi_buf = (unsigned short)val >> (16 - s->bi_valid);
                s->bi_valid += len - 16;
            } else {
                s->bi_buf |=
                    (unsigned short)(s->bl_tree[gZlibExtraLBitsBlOrder.bl_order[rank]].dl)
                    << s->bi_valid;
                s->bi_valid += len;
            }
        };
    }
    send_tree(s, (ct_data *)s->dyn_ltree, lcodes - 1); /* literal tree */
    send_tree(s, (ct_data *)s->dyn_dtree, dcodes - 1); /* distance tree */
}

uint32_t __fastcall _tr_tally(deflate_state * s, int32_t dist, int32_t lc) {
    s->d_buf[s->last_lit] = (uint16_t)dist;
    s->l_buf[s->last_lit] = (uint8_t)lc;
    s->last_lit++;
    if (!dist) {
      s->dyn_ltree[lc].fc++;
    } else {
      uint8_t byDistCode;
      s->matches++;
      s->dyn_ltree[_length_code[lc] + 0x101].fc++;
      if (dist - 1U < 0x100) {
        byDistCode = *(uint8_t*)((char*)_dist_code + dist - 1);
      } else {
        byDistCode = _dist_code[(dist - 1U >> 7) + 0x100];
      }

      s->dyn_dtree[byDistCode].fc++;
    }

    return (uint32_t)(s->last_lit == s->lit_bufsize - 1);
}

