static void __stdcall gen_codes(ct_data * tree, int32_t max_code, uint16_t * bl_count) {
    uint32_t nCodeIn;
    uint32_t nReversedPrev;
    uint32_t nLen;
    uint32_t nLowBit;
    uint16_t awNextCode[16];
    uint32_t nReversed;
    int nBits = 1;
    uint16_t wCode = 0;
    do {
      wCode = (bl_count[nBits - 1] + wCode) * 2;
      awNextCode[nBits] = wCode;
      nBits++;
    } while (nBits <= 0xf);

    for (nBits = 0; nBits <= max_code; nBits++) {
      nLen = (uint32_t)tree[nBits].dl;
      if (nLen) {
        nCodeIn = (uint32_t)awNextCode[nLen];
        awNextCode[nLen]++;
        nReversed = 0;
        do {
          nReversedPrev = nReversed;
          nLowBit = nCodeIn & 1;
          nLen--;
          nCodeIn >>= 1;
          nReversed = (nReversedPrev | nLowBit) * 2;
        } while ((int)nLen > 0);

        tree[nBits].fc = (uint16_t)nReversedPrev | (uint16_t)nLowBit;
      }
    }
}

static void __stdcall build_tree(tree_desc * desc, deflate_state * s) {
    int32_t nNodeM;
    int nNodeSecond;
    ct_data* tree = desc->dyn_tree;
    int nNode = desc->stat_desc->elems;
    ct_data* pStatTree = desc->stat_desc->static_tree;
    int nIndex = 0;
    int nMaxCode = -1;
    s->heap_len = 0;
    s->heap_max = 0x23d;
    if (nNode > 0) {
      do {
        if (tree[nIndex].fc) {
          s->heap_len++;
          s->heap[s->heap_len] = nIndex;
          s->depth[nIndex] = '\0';
          nMaxCode = nIndex;
        } else {
          tree[nIndex].dl = 0;
        }

        nIndex++;
      } while (nIndex < nNode);
    }

    nIndex = s->heap_len;
    while (nIndex < 2) {
      if (nMaxCode < 2) {
        nIndex = nMaxCode + 1;
        nMaxCode = nIndex;
      } else {
        nIndex = 0;
      }

      s->heap_len++;
      s->heap[s->heap_len] = nIndex;
      tree[nIndex].fc = 1;
      s->depth[nIndex] = '\0';
      s->opt_len--;
      if (pStatTree) {
        s->static_len -= (uint32_t)pStatTree[nIndex].dl;
      }

      nIndex = s->heap_len;
    }

    desc->max_code = nMaxCode;
    for (nIndex = s->heap_len / 2; nIndex >= 1; nIndex--) {
      pqdownheap(nIndex, s, tree);
    }

    do {
      uint8_t byMaxDepth;
      nNodeM = s->heap[s->heap_len];
      nIndex = s->heap[1];
      s->heap_len--;
      s->heap[1] = nNodeM;
      pqdownheap(1, s, tree);
      nNodeSecond = s->heap[1];
      s->heap_max--;
      s->heap[s->heap_max] = nIndex;
      s->heap_max--;
      s->heap[s->heap_max] = nNodeSecond;
      tree[nNode].fc = tree[nNodeSecond].fc + tree[nIndex].fc;
      byMaxDepth = s->depth[nIndex];
      if (s->depth[nIndex] < s->depth[nNodeSecond]) {
        byMaxDepth = s->depth[nNodeSecond];
      }

      s->depth[nNode] = byMaxDepth + 1;
      tree[nNodeSecond].dl = (uint16_t)nNode;
      tree[nIndex].dl = (uint16_t)nNode;
      s->heap[1] = nNode;
      nNode++;
      pqdownheap(1, s, tree);
    } while (s->heap_len >= 2);

    s->heap_max--;
    s->heap[s->heap_max] = s->heap[1];
    gen_bitlen(desc, s);
    gen_codes(tree, nMaxCode, s->bl_count);
}

static int32_t build_bl_tree(deflate_state * s) {
    int max_blindex; /* index of last bit length code of non zero freq */
    /* Determine the bit length frequencies for literal and distance trees */
    scan_tree(s->l_desc.max_code, s, (ct_data *)s->dyn_ltree);
    scan_tree(s->d_desc.max_code, s, (ct_data *)s->dyn_dtree);
    /* Build the bit length tree: */
    build_tree((tree_desc *)(&(s->bl_desc)), s);
    /* opt_len now includes the length of the tree representations, except
     * the lengths of the bit lengths codes and the 5+5+4 bits for the counts.
     */
    /* Determine the number of bit length codes to send. The pkzip format
     * requires that at least 4 bit length codes be sent. (appnote.txt says
     * 3 but the actual value used is 4.)
     */
    for (max_blindex = 19 - 1; max_blindex >= 3; max_blindex--) {
        if (s->bl_tree[gZlibExtraLBitsBlOrder.bl_order[max_blindex]].dl != 0)
            break;
    }
    /* Update opt_len to include the bit length tree and counts */
    s->opt_len += 3 * (max_blindex + 1) + 5 + 5 + 4;
    return max_blindex;
}

void __fastcall _tr_stored_block(deflate_state * s, char * buf, uint32_t stored_len, int32_t last) {
    int nBitCount = s->bi_valid;
    if (nBitCount > 0xd) {
      uint8_t byBitBufHi;
      s->bi_buf |= (uint16_t)(last << D2_SHIFT_COUNT(nBitCount));
      s->pending_buf[s->pending] = (uint8_t)s->bi_buf;
      byBitBufHi = *(uint8_t*)((intptr_t)&s->bi_buf + 1);
      s->pending++;
      s->pending_buf[s->pending] = byBitBufHi;
      nBitCount = s->bi_valid;
      s->pending++;
      s->bi_valid = nBitCount - 0xd;
      s->bi_buf = (uint16_t)last >> D2_SHIFT_COUNT(0x10U - nBitCount);
    } else {
      s->bi_valid = nBitCount + 3;
      s->bi_buf |= (uint16_t)(last << D2_SHIFT_COUNT(nBitCount));
    }

    copy_block(s, (uint8_t*)buf, stored_len, 1);
}

void __fastcall _tr_flush_bits(deflate_state * s) {
    bi_flush(s);
}

void __fastcall _tr_align(deflate_state * s) {
    int nBitCount = s->bi_valid;
    s->bi_buf |= (uint16_t)(2 << D2_SHIFT_COUNT(nBitCount));
    if (nBitCount > 0xd) {
      s->pending_buf[s->pending] = (uint8_t)s->bi_buf;
      s->pending++;
      s->pending_buf[s->pending] = *(uint8_t*)((intptr_t)&s->bi_buf + 1);
      nBitCount = s->bi_valid;
      s->pending++;
      uint16_t wBits = 2;
      wBits >>= D2_SHIFT_COUNT(0x10U - nBitCount);
      s->bi_buf = wBits;
      nBitCount -= 13;
      s->bi_valid = nBitCount;
    } else {
      s->bi_valid = nBitCount + 3;
    }

    nBitCount = s->bi_valid;
    s->bi_buf |= (uint16_t)(0 << D2_SHIFT_COUNT(nBitCount));
    if (nBitCount > 9) {
      s->pending_buf[s->pending] = (uint8_t)s->bi_buf;
      s->pending++;
      s->pending_buf[s->pending] = *(uint8_t*)((intptr_t)&s->bi_buf + 1);
      s->pending++;
      nBitCount = s->bi_valid;
      uint16_t wBits = 0;
      wBits >>= D2_SHIFT_COUNT(0x10U - nBitCount);
      s->bi_buf = wBits;
      nBitCount -= 9;
      s->bi_valid = nBitCount;
    } else {
      s->bi_valid = nBitCount + 7;
    }

    bi_flush(s);
}

void __fastcall _tr_flush_block(deflate_state * s, char * buf, uint32_t stored_len, int32_t last) {
    uint32_t opt_lenb, static_lenb; /* opt_len and static_len in bytes */
    int max_blindex = 0;            /* index of last bit length code of non zero freq */
    /* Build the Huffman trees unless a stored block is forced */
    if (s->level > 0) {
        /* Check if the file is binary or text */
        if (s->strm->data_type == 2)
            s->strm->data_type = detect_data_type(s);
        /* Construct the literal and distance trees */
        build_tree((tree_desc *)(&(s->l_desc)), s);
        build_tree((tree_desc *)(&(s->d_desc)), s);
        /* At this point, opt_len and static_len are the total bit lengths of
         * the compressed block data, excluding the tree representations.
         */
        /* Build the bit length tree for the above two trees, and get the index
         * in bl_order of the last bit length code to send.
         */
        max_blindex = build_bl_tree(s);
        /* Determine the best encoding. Compute the block lengths in bytes. */
        opt_lenb = (s->opt_len + 3 + 7) >> 3;
        static_lenb = (s->static_len + 3 + 7) >> 3;
        if (static_lenb <= opt_lenb)
            opt_lenb = static_lenb;
    } else {
        opt_lenb = static_lenb = stored_len + 5; /* force a stored block */
    }
    if (stored_len + 4 <= opt_lenb && buf != (char *)0) {
        /* 4: two words for the lengths */
        /* The test buf != NULL is only necessary if LIT_BUFSIZE > WSIZE.
         * Otherwise we can't have processed more than WSIZE input bytes since
         * the last block flush, because compression would have been
         * successful. If LIT_BUFSIZE <= WSIZE, it is never too late to
         * transform a block into a stored block.
         */
        _tr_stored_block(s, buf, stored_len, last);
    } else if (s->strategy == 4 || static_lenb == opt_lenb) {
        {
            int len = 3;
            if (s->bi_valid > (int)16 - len) {
                int val = (1 << 1) + last;
                s->bi_buf |= (unsigned short)val << s->bi_valid;
                {
                    {
                        s->pending_buf[s->pending++] =
                            ((unsigned char)((s->bi_buf) & 0xff));
                    };
                    {
                        s->pending_buf[s->pending++] =
                            ((unsigned char)((unsigned short)(s->bi_buf) >> 8));
                    };
                };
                s->bi_buf = (unsigned short)val >> (16 - s->bi_valid);
                s->bi_valid += len - 16;
            } else {
                s->bi_buf |= (unsigned short)((1 << 1) + last) << s->bi_valid;
                s->bi_valid += len;
            }
        };
        compress_block((ct_data *)static_ltree, (ct_data *)static_dtree, s);
    } else {
        {
            int len = 3;
            if (s->bi_valid > (int)16 - len) {
                int val = (2 << 1) + last;
                s->bi_buf |= (unsigned short)val << s->bi_valid;
                {
                    {
                        s->pending_buf[s->pending++] =
                            ((unsigned char)((s->bi_buf) & 0xff));
                    };
                    {
                        s->pending_buf[s->pending++] =
                            ((unsigned char)((unsigned short)(s->bi_buf) >> 8));
                    };
                };
                s->bi_buf = (unsigned short)val >> (16 - s->bi_valid);
                s->bi_valid += len - 16;
            } else {
                s->bi_buf |= (unsigned short)((2 << 1) + last) << s->bi_valid;
                s->bi_valid += len;
            }
        };
        send_all_trees(s->l_desc.max_code + 1, s->d_desc.max_code + 1, max_blindex + 1,
                       s);
        compress_block((ct_data *)s->dyn_ltree, (ct_data *)s->dyn_dtree, s);
    }
    /* The above check is made mod 2^32, for files larger than 512 MB
     * and uLong implemented on 32 bits.
     */
    init_block(s);
    if (last) {
        bi_windup(s);
    }
}

